fn reverse(a: &Vec<i32>) -> Vec<i32> {
    // Pre‐allocate a new vector of the same length for efficiency
    let mut a_rev = Vec::with_capacity(a.len());
    // Iterate over `a` in reverse order, pushing each item into `a_rev`
    for &value in a.iter().rev() {
        a_rev.push(value);
    }
    a_rev
}

fn main() {
    let empty: Vec<i32> = vec![];
    let single = vec![42];
    let nums = vec![1, 2, 3, 4, 5];

    assert_eq!(reverse(&empty), vec![]);
    assert_eq!(reverse(&single), vec![42]);
    assert_eq!(reverse(&nums), vec![5, 4, 3, 2, 1]);

    println!("All tests passed!");
}